/*
 * Shared keyframes. Components pick them with `animation-name` and set
 * duration and easing from the motion tokens in tokens.css. Plain CSS, so the
 * Vue version can reuse this file unchanged.
 */
@keyframes distill-fade-in {
	from {
		opacity: 0;
	}
}

@keyframes distill-fade-out {
	to {
		opacity: 0;
	}
}

/* Fade + scale from 95%, the standard dialog / popover entrance. */
@keyframes distill-zoom-in {
	from {
		opacity: 0;
		scale: 0.95;
	}
}

@keyframes distill-zoom-out {
	to {
		opacity: 0;
		scale: 0.95;
	}
}

/* Slide in a short distance from a side. Uses `translate` so it composes with transforms. */
@keyframes distill-slide-in-from-top {
	from {
		translate: 0 calc(var(--dui-space-2) * -1);
	}
}

@keyframes distill-slide-in-from-bottom {
	from {
		translate: 0 var(--dui-space-2);
	}
}

@keyframes distill-slide-in-from-left {
	from {
		translate: calc(var(--dui-space-2) * -1) 0;
	}
}

@keyframes distill-slide-in-from-right {
	from {
		translate: var(--dui-space-2) 0;
	}
}

/* Loading placeholders (Skeleton). */
@keyframes distill-pulse {
	50% {
		opacity: 0.5;
	}
}

/* distill-ui design tokens. See /docs/theming. */
@import './keyframes.css';

/* ========================================================================== */
/* 1. Seed colors                                                             */
/* ========================================================================== */

:root {
	/* Primary presets */
	--dui-blue: oklch(0.556 0.2 260);
	--dui-cyan: oklch(0.556 0.12 225);
	--dui-violet: oklch(0.556 0.2 285);
	--dui-forest: oklch(0.556 0.15 150);
	--dui-ember: oklch(0.556 0.19 35);

	/* Gray presets */
	--dui-gray-neutral: oklch(0.556 0 0);
	--dui-gray-slate: oklch(0.556 0.02 260);
	--dui-gray-stone: oklch(0.556 0.013 58);

	/* Seeds: point at a preset, or set any oklch() */
	--dui-primary: var(--dui-blue);
	--dui-neutral: var(--dui-gray-slate);
	--dui-destructive: oklch(0.577 0.245 27.325);
	--dui-success: oklch(0.6 0.17 150);
}

/* Layers 2 and 3 are worked out again wherever a theme or seeds are set. */
:root,
.light,
.dark,
[data-theme],
.dui-theme {
	/* ====================================================================== */
	/* 2. Color scales                                                        */
	/* Same lightness per step for both. Chroma peaks at 500.                 */
	/* ====================================================================== */

	/* Neutral */
	--dui-neutral-50: oklch(from var(--dui-neutral) 0.985 calc(c * 0.1) h);
	--dui-neutral-100: oklch(from var(--dui-neutral) 0.96 calc(c * 0.15) h);
	--dui-neutral-200: oklch(from var(--dui-neutral) 0.922 calc(c * 0.3) h);
	--dui-neutral-300: oklch(from var(--dui-neutral) 0.87 calc(c * 0.5) h);
	--dui-neutral-400: oklch(from var(--dui-neutral) 0.708 calc(c * 0.85) h);
	--dui-neutral-500: oklch(from var(--dui-neutral) 0.53 c h);
	--dui-neutral-600: oklch(from var(--dui-neutral) 0.439 calc(c * 0.95) h);
	--dui-neutral-700: oklch(from var(--dui-neutral) 0.371 calc(c * 0.85) h);
	--dui-neutral-800: oklch(from var(--dui-neutral) 0.269 calc(c * 0.7) h);
	--dui-neutral-900: oklch(from var(--dui-neutral) 0.205 calc(c * 0.55) h);
	--dui-neutral-950: oklch(from var(--dui-neutral) 0.145 calc(c * 0.4) h);

	/* Primary */
	--dui-primary-50: oklch(from var(--dui-primary) 0.985 calc(c * 0.1) h);
	--dui-primary-100: oklch(from var(--dui-primary) 0.97 calc(c * 0.15) h);
	--dui-primary-200: oklch(from var(--dui-primary) 0.922 calc(c * 0.3) h);
	--dui-primary-300: oklch(from var(--dui-primary) 0.87 calc(c * 0.5) h);
	--dui-primary-400: oklch(from var(--dui-primary) 0.708 calc(c * 0.85) h);
	--dui-primary-500: oklch(from var(--dui-primary) 0.53 c h);
	--dui-primary-600: oklch(from var(--dui-primary) 0.439 calc(c * 0.95) h);
	--dui-primary-700: oklch(from var(--dui-primary) 0.371 calc(c * 0.85) h);
	--dui-primary-800: oklch(from var(--dui-primary) 0.269 calc(c * 0.7) h);
	--dui-primary-900: oklch(from var(--dui-primary) 0.205 calc(c * 0.55) h);
	--dui-primary-950: oklch(from var(--dui-primary) 0.145 calc(c * 0.4) h);

	/* Fixed */
	--dui-white: oklch(1 0 0);
	--dui-black: oklch(0 0 0);

	/* ====================================================================== */
	/* 3. Semantic colors                                                     */
	/* What components read. Each is light-dark(light value, dark value).     */
	/* ====================================================================== */

	/* Page */
	--dui-color-background: light-dark(var(--dui-white), var(--dui-neutral-950));
	--dui-color-foreground: light-dark(var(--dui-neutral-900), var(--dui-neutral-50));

	/* Card and popover */
	--dui-color-card: light-dark(var(--dui-neutral-50), var(--dui-neutral-900));
	--dui-color-card-foreground: var(--dui-color-foreground);
	--dui-color-popover: light-dark(var(--dui-white), var(--dui-neutral-900));
	--dui-color-popover-foreground: var(--dui-color-foreground);

	/* Primary */
	--dui-color-primary: var(--dui-primary-500);
	--dui-color-primary-hover: var(--dui-primary-600);
	--dui-color-primary-foreground: var(--dui-primary-50);
	--dui-color-primary-text: light-dark(var(--dui-primary-600), var(--dui-primary-300));

	/* Secondary */
	--dui-color-secondary: light-dark(var(--dui-neutral-100), var(--dui-neutral-800));
	--dui-color-secondary-hover: light-dark(var(--dui-neutral-200), var(--dui-neutral-700));
	--dui-color-secondary-foreground: light-dark(var(--dui-neutral-900), var(--dui-neutral-50));

	/* Muted */
	--dui-color-muted: light-dark(var(--dui-neutral-100), var(--dui-neutral-800));
	--dui-color-muted-foreground: light-dark(var(--dui-neutral-600), var(--dui-neutral-300));

	/* Accent */
	--dui-color-accent: light-dark(var(--dui-neutral-100), var(--dui-neutral-700));
	--dui-color-accent-foreground: light-dark(var(--dui-neutral-900), var(--dui-neutral-50));

	/* Destructive */
	--dui-color-destructive: var(--dui-destructive);
	--dui-color-destructive-foreground: var(--dui-white);
	--dui-color-destructive-subtle: color-mix(in oklch, var(--dui-destructive) 10%, transparent);
	--dui-color-destructive-subtle-hover: color-mix(
		in oklch,
		var(--dui-destructive) 20%,
		transparent
	);
	--dui-color-destructive-text: light-dark(
		color-mix(in oklab, var(--dui-destructive) 80%, var(--dui-black)),
		color-mix(in oklab, var(--dui-destructive) 40%, var(--dui-white))
	);

	/* Success */
	--dui-color-success: var(--dui-success);

	/* Borders and focus */
	--dui-color-border: light-dark(var(--dui-neutral-200), var(--dui-neutral-800));
	--dui-color-input: light-dark(var(--dui-neutral-200), var(--dui-neutral-800));
	--dui-color-ring: var(--dui-primary-400);

	/* Overlay */
	--dui-color-overlay: light-dark(
		oklch(from var(--dui-black) l c h / 10%),
		oklch(from var(--dui-black) l c h / 50%)
	);

	/* Controls */
	--dui-color-control: light-dark(transparent, var(--dui-neutral-900));
	--dui-color-control-hover: light-dark(var(--dui-neutral-100), var(--dui-neutral-800));
	--dui-color-tab-active: light-dark(var(--dui-white), var(--dui-color-control));
	--dui-color-tab-active-border: light-dark(transparent, var(--dui-color-input));
	--dui-color-switch-track: light-dark(var(--dui-neutral-200), var(--dui-neutral-800));
	--dui-color-switch-thumb: light-dark(var(--dui-white), var(--dui-color-foreground));
	--dui-color-switch-thumb-checked: var(--dui-color-primary-foreground);
}

/* ========================================================================== */
/* 4. Light and dark                                                          */
/* ========================================================================== */

:root {
	color-scheme: light dark;
}

.light,
[data-theme='light'] {
	color-scheme: light;
}

.dark,
[data-theme='dark'] {
	color-scheme: dark;
}

:root {
	/* ====================================================================== */
	/* 5. Spacing                                                             */
	/* ====================================================================== */

	--dui-space-0-5: 0.125rem;
	--dui-space-1: 0.25rem;
	--dui-space-1-5: 0.375rem;
	--dui-space-2: 0.5rem;
	--dui-space-2-5: 0.625rem;
	--dui-space-3: 0.75rem;
	--dui-space-4: 1rem;
	--dui-space-5: 1.25rem;
	--dui-space-6: 1.5rem;
	--dui-space-8: 2rem;
	--dui-space-10: 2.5rem;
	--dui-space-12: 3rem;

	/* ====================================================================== */
	/* 6. Radius                                                              */
	/* ====================================================================== */

	--dui-radius: 0.625rem;
	--dui-radius-sm: calc(var(--dui-radius) * 0.6);
	--dui-radius-md: calc(var(--dui-radius) * 0.8);
	--dui-radius-lg: var(--dui-radius);
	--dui-radius-xl: calc(var(--dui-radius) * 1.4);
	--dui-radius-full: 9999px;

	/* ====================================================================== */
	/* 7. Shadows                                                             */
	/* ====================================================================== */

	--dui-shadow-xs: 0 1px 2px 0 oklch(0 0 0 / 5%);
	--dui-shadow-sm: 0 1px 3px 0 oklch(0 0 0 / 10%), 0 1px 2px -1px oklch(0 0 0 / 10%);
	--dui-shadow-md: 0 4px 6px -1px oklch(0 0 0 / 10%), 0 2px 4px -2px oklch(0 0 0 / 10%);
	--dui-shadow-lg: 0 10px 15px -3px oklch(0 0 0 / 10%), 0 4px 6px -4px oklch(0 0 0 / 10%);

	/* ====================================================================== */
	/* 8. Typography                                                          */
	/* ====================================================================== */

	/* Families */
	--dui-font-sans:
		ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
	--dui-font-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, 'Liberation Mono', monospace;

	/* Sizes */
	--dui-text-xs: 0.75rem;
	--dui-text-xs-line-height: 1rem;
	--dui-text-sm: 0.875rem;
	--dui-text-sm-line-height: 1.25rem;
	--dui-text-base: 1rem;
	--dui-text-base-line-height: 1.5rem;
	--dui-text-lg: 1.125rem;
	--dui-text-lg-line-height: 1.75rem;

	/* Weights */
	--dui-weight-normal: 400;
	--dui-weight-medium: 500;
	--dui-weight-semibold: 600;

	/* ====================================================================== */
	/* 9. Focus ring                                                          */
	/* ====================================================================== */

	--dui-ring-width: 3px;

	/* ====================================================================== */
	/* 10. Motion                                                             */
	/* ====================================================================== */

	/* Durations */
	--dui-duration-fast: 100ms;
	--dui-duration-normal: 150ms;
	--dui-duration-slow: 200ms;
	--dui-duration-pulse: 2s;

	/* Easings */
	--dui-ease-out: cubic-bezier(0, 0, 0.2, 1);
	--dui-ease-in: cubic-bezier(0.4, 0, 1, 1);
	--dui-ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);

	/* ====================================================================== */
	/* 11. Stacking                                                           */
	/* ====================================================================== */

	--dui-z-dropdown: 50;
	--dui-z-overlay: 50;
	--dui-z-modal: 50;
	--dui-z-popover: 50;
	--dui-z-toast: 100;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
	:root {
		--dui-duration-fast: 0ms;
		--dui-duration-normal: 0ms;
		--dui-duration-slow: 0ms;
		--dui-duration-pulse: 0ms;
	}
}
